$ErrorActionPreference = 'Continue'; $site = (Resolve-Path .venv\Lib\site-packages -ErrorAction Stop).Path; $env:PYTHONPATH = "$site;$site\win32;$site\win32\lib"; $env:PATH = "$site\pywin32_system32;$env:PATH"; $venvPython = (Resolve-Path .venv\Scripts\python.exe -ErrorAction Stop).Path; $python = (& $venvPython -c "import os, sys; base = os.path.join(sys.base_prefix, 'python.exe'); print(base if os.path.isfile(base) else sys.executable)").Trim(); if ($LASTEXITCODE -ne 0 -or -not $python) { throw 'Cannot locate Python.' }; & $python -m PyInstaller --noconfirm --clean --distpath dist --workpath "build\pyinstaller" "packaging\PupilMonitor.spec"; if ($LASTEXITCODE -ne 0) { throw 'PyInstaller build failed.' }; & $python "scripts\bundle-notices.py" "dist\PupilMonitor"; if ($LASTEXITCODE -ne 0) { throw 'Could not collect dependency notices.' }; Copy-Item -LiteralPath "README.md" -Destination "dist\PupilMonitor" -Force -ErrorAction Stop; Copy-Item -LiteralPath "packaging\PORTABLE.txt" -Destination "dist\PupilMonitor\BAT-DAU.txt" -Force -ErrorAction Stop; Copy-Item -LiteralPath "scripts\install-bundled-service.ps1" -Destination "dist\PupilMonitor\Install-Service.ps1" -Force -ErrorAction Stop; $version = (& $python -c "import pathlib,tomllib; print(tomllib.loads(pathlib.Path('pyproject.toml').read_text(encoding='utf-8'))['project']['version'])").Trim(); if ($LASTEXITCODE -ne 0) { throw 'Cannot read package version.' }; $archive = "dist\PupilMonitor-$version-Windows-x64.zip"; Compress-Archive -LiteralPath "dist\PupilMonitor" -DestinationPath $archive -Force -ErrorAction Stop; Write-Host "Executable: $(Join-Path (Resolve-Path 'dist\PupilMonitor').Path 'PupilMonitor.exe')"; Write-Host "Portable ZIP: $(Join-Path (Resolve-Path 'dist').Path "PupilMonitor-$version-Windows-x64.zip")"